  -b "(Parameter.set 'Audio_Method 'Audio_Command)" \
  -b "(Parameter.set 'Audio_Command \\"\\")" \
  -b "(utt.relation.print (SayText \\" \$\{TEXT\} \\") 'Segment)";`;

  const options = {
    cwd: localFolder,
    timeout: 10000,
    encoding: 'buffer',
  };

  console.log(`Running command - \n${cmd}`);

